"""Golden results generated by the original R GIFT functions, not Python."""
import hashlib
import json
from pathlib import Path
import sys
import warnings

import numpy as np
import pandas as pd
import pytest

ROOT = Path(__file__).resolve().parents[1]
REFERENCE = ROOT / "tests/r_reference"
sys.path.insert(0, str(ROOT))
sys.path.insert(0, str(ROOT / "model"))
from gift_habitat import avg_hydraulics, habitat, model_reaches
from habitat_engine import aggregate_period, compute_monthly, load_dataset

CASES = pd.read_csv(REFERENCE / "hydraulic_cases.csv").to_dict("records")
HYDRAULIC_COLUMNS = ["Q", "Ai", "Wi", "di", "Ui"]


def arguments(case):
    return {key: case[field] for key, field in
            (("max_bankfull_depth", "db_max"), ("shape_factor", "b_value"))
            if pd.notna(case[field])}


def test_reference_provenance_and_input_hashes():
    provenance = json.loads((REFERENCE / "provenance.json").read_text())
    assert provenance["source_revision"] == "40c4a74f82d842cd2ab8ab4c53e2b985ac4e0030"
    assert provenance["R_version"].startswith("R version")
    for entry in pd.read_csv(REFERENCE / "source_hashes.csv").to_dict("records"):
        folder = REFERENCE / "source" if entry["file"].endswith(".R") else ROOT / "inputs/curves"
        assert hashlib.md5((folder / entry["file"]).read_bytes()).hexdigest() == entry["md5"]


@pytest.mark.parametrize("case", CASES, ids=[c["case"] for c in CASES])
def test_hydraulics_against_original_r(case):
    grid = pd.read_csv(REFERENCE / "hydraulics.csv")
    expected = grid[grid.case.eq(case["case"])][HYDRAULIC_COLUMNS]
    with warnings.catch_warnings():
        warnings.simplefilter("ignore", UserWarning)
        actual = avg_hydraulics(case["S"], case["wb"], case["db"], case["D84"], **arguments(case))
        native = avg_hydraulics(case["S"], case["wb"], case["db"], case["D84"],
                                full_curve=True, **arguments(case))
    assert len(actual) == len(expected)
    np.testing.assert_allclose(actual[HYDRAULIC_COLUMNS], expected, rtol=2e-9, atol=2e-11)
    expected_native = pd.read_csv(REFERENCE / "native_levels.csv")
    expected_native = expected_native[expected_native.case.eq(case["case"])]
    np.testing.assert_allclose(native.iloc[expected_native["rank"]][HYDRAULIC_COLUMNS],
                               expected_native[HYDRAULIC_COLUMNS], rtol=2e-9, atol=2e-11)
    metadata = pd.read_csv(REFERENCE / "hydraulic_metadata.csv").set_index("case").loc[case["case"]]
    assert actual.attrs["shape_factor"] == pytest.approx(metadata["shape"], abs=2e-15)
    assert actual.attrs["shape_factor_capped"] is False
    assert actual.attrs["simulated_max_depth_m"] == pytest.approx(metadata.max_depth, rel=2e-12)
    assert actual.attrs["simulated_bankfull_discharge_m3s"] == pytest.approx(metadata.q_max, rel=2e-9, abs=2e-11)
    if metadata["shape"] > .7:
        assert actual.attrs["shape_factor"] > .7


@pytest.mark.parametrize("factor", [-.01, 1.0, 1.1])
def test_invalid_shapes_are_rejected(factor):
    with pytest.raises(ValueError, match="shape_factor"):
        avg_hydraulics(.002, 10, .5, 60, shape_factor=factor)


def test_batch_preserves_high_shapes_and_reports_exceedances():
    reaches = pd.DataFrame([dict(id=1, slope=.01, width=5., depth=.25,
                                 max_depth=1., d84=50.)])
    key = "chinook_juvenile_rearing"
    result = model_reaches(reaches,
        pd.read_csv(ROOT / f"inputs/curves/{key}_depth.csv"),
        pd.read_csv(ROOT / f"inputs/curves/{key}_velocity.csv"),
        slope_col="slope", width_col="width", depth_col="depth", d84_col="d84",
        id_col="id", max_depth_col="max_depth")
    assert result.GIFT_shape_factor_used.iloc[0] == pytest.approx(.75)
    assert result.GIFT_shape_factor_raw.iloc[0] == pytest.approx(.75)
    assert result.attrs["shape_factor_exceedances"] == [(1, .75)]


@pytest.mark.parametrize("mode", ["none", "distribution", "D84_proxy"])
def test_habitat_against_original_r(mode):
    inputs = pd.read_csv(REFERENCE / "habitat_inputs.csv")
    expected = pd.read_csv(REFERENCE / "habitat.csv")
    expected = expected[expected.substrate_mode.eq(mode)]
    for curve, rows in expected.groupby("curve", sort=False):
        depth = pd.read_csv(ROOT / f"inputs/curves/{curve}_depth.csv")
        velocity = pd.read_csv(ROOT / f"inputs/curves/{curve}_velocity.csv")
        substrate = pd.read_csv(ROOT / f"inputs/curves/{curve}_substrate.csv")
        kwargs = {}
        if mode == "distribution":
            kwargs = dict(substrate_curve=substrate, gsd=[1, 2, 5, 10, 20, 40, 60, 100, 200, 400])
        elif mode == "D84_proxy":
            kwargs = dict(substrate_curve=substrate, substrate_size_mm=100)
        actual = habitat(inputs[HYDRAULIC_COLUMNS], depth, velocity, **kwargs)
        cols = ["Q", "d.suit", "v.suit", "s.suit", "w", "WUA"]
        np.testing.assert_allclose(actual[cols], rows.sort_values("input_row")[cols],
                                   rtol=0, atol=2e-12)


@pytest.fixture(scope="module")
def r_monthly():
    # The frozen R results belong to their frozen geometry inputs, which can
    # differ from the user's current GeoPackage. Never compare old R outputs
    # with new source geometry or regenerate reference values using Python.
    _, curves = load_dataset(ROOT / "data")
    reference = pd.read_csv(REFERENCE / "monthly.csv")
    reference = reference[reference.curve.isin(c["id"] for c in curves)]
    flows = pd.read_csv(REFERENCE / "monthly_inputs.csv")
    features = []
    for case in CASES:
        if not case["case"].startswith("reach_"):
            continue
        comid = int(case["case"].removeprefix("reach_"))
        with warnings.catch_warnings():
            warnings.simplefilter("ignore", UserWarning)
            hyd = avg_hydraulics(case["S"], case["wb"], case["db"], case["D84"],
                                 full_curve=True, **arguments(case))
        months = []
        for row in flows[flows.id.eq(comid)].sort_values("month").itertuples():
            q = row.q
            status = ("missing_flow" if pd.isna(q) or q < 0 else "zero_flow" if q == 0
                      else "below_range" if q < hyd.Q.min()
                      else "above_bankfull" if q > hyd.Q.max() else "ok")
            values = [float(np.interp(q, hyd.Q, hyd[key])) for key in ("di", "Ui", "Wi")] if status == "ok" else [None] * 3
            months.append([q, *values, status])
        features.append(dict(id=comid, d84=case["D84"], summerWidth=1., months=months))
    return reference, {c["id"]: compute_monthly(features, c) for c in curves}


def test_application_monthly_habitat_against_r(r_monthly):
    reference, computed = r_monthly
    cols = ["q", "depth", "velocity", "width", "d", "v", "s", "hsi", "wua"]
    for key, expected in reference.groupby("curve", sort=False):
        actual = computed[key].set_index(["id", "month"]).sort_index()
        expected = expected.set_index(["id", "month"]).sort_index()
        assert actual.index.equals(expected.index)
        assert actual.status.equals(expected.status)
        np.testing.assert_allclose(actual[cols], expected[cols], rtol=2e-9, atol=2e-11, equal_nan=True)


@pytest.mark.parametrize("months", [[7, 8, 9], [3, 4, 5, 6], [11, 12, 1, 2], [8]])
@pytest.mark.parametrize("require_all", [True, False])
def test_period_medians_from_r_monthly_results(r_monthly, months, require_all):
    reference, computed = r_monthly
    columns = ["depth", "velocity", "width", "d", "v", "hsi", "wua"]
    for key, expected in reference.groupby("curve", sort=False):
        result = aggregate_period(computed[key], months, require_all)
        for comid, rows in expected[expected.month.isin(months)].groupby("id"):
            supported = rows[rows.hsi.notna()]
            assert result.at[comid, "validCount"] == len(supported)
            if supported.empty or (require_all and len(supported) != len(months)):
                assert result.loc[comid, columns].isna().all()
            else:
                np.testing.assert_allclose(result.loc[comid, columns].to_numpy(dtype=float),
                                           supported[columns].median().to_numpy(),
                                           rtol=2e-9, atol=2e-11)
